<script setup lang="ts">
import type { ActionResult, AssetRow, WorkflowAction } from '../../types/domain'
import { documentKinds } from '../../types/domain'
import { dateLabel, initials, money, stage, statusSeverity } from '../../utils/format'
import { currentDocuments, missingKinds, nextTask, requiredKinds } from '../../utils/workflow'
import { downloadDemo } from '../../utils/download'

const route = useRoute()
const { cases, role, today, act } = useMockApp()
const expediente = computed(() => cases.value.find(item => item.id === route.params.id))
if (!expediente.value) throw createError({ statusCode: 404, statusMessage: 'Expediente no encontrado' })
const item = computed(() => expediente.value!)
const tab = ref('ph')
const feedback = ref<ActionResult | null>(null)
const fileKind = ref('DNI anverso')
const dniUntil = ref(item.value.identity.dniValidUntil ?? '')
watch(() => item.value.identity.dniValidUntil, value => { dniUntil.value = value ?? '' })
const rows = ref<AssetRow[]>(item.value.extraction.rows.map(row => ({ ...row })))
watch(() => item.value.extraction.rows, value => { rows.value = value.map(row => ({ ...row })) })
const readonly = computed(() => item.value.tax.state === 'Cerrado' || ['Retirado', 'No interesado'].includes(item.value.contact))
type Modal = 'ph-approve' | 'ph-changes' | 'ph-edit' | 'pbc-apt' | 'pbc-issue' | 'pbc-no' | 'nav' | 'prior' | 'doc-reject' | 'criteria' | 'present' | 'invoice' | 'it-report' | 'it-resolve' | 'call' | 'assign' | 'nav-info'
const modal = ref<Modal | null>(null)
const note = ref('')
const reference = ref('')
const fee = ref(item.value.fee)
const actionDate = ref(today.value)
const docId = ref('')
const callOutcome = ref<'Sigue interesado' | 'Sin contacto' | 'No interesado'>('Sin contacto')
const owner = ref(item.value.owner)
const title = computed(() => ({
  'ph-approve': 'Aprobar propuesta', 'ph-changes': 'Solicitar cambios de la PH', 'ph-edit': 'Nueva versión de honorarios',
  'pbc-apt': 'PBC: continuar tras revisión', 'pbc-issue': 'Registrar incidencia PBC', 'pbc-no': 'PBC: no apto',
  nav: 'Registrar alta NAV manual', prior: 'Confirmar antecedentes históricos', 'doc-reject': 'Solicitar sustitución',
  criteria: 'Registrar carga manual en Criteria', present: 'Registrar presentación ficticia', invoice: 'Emitir factura / minuta',
  'it-report': 'Desviación del extractor', 'it-resolve': 'Registrar ajuste IT', call: 'Resultado de llamada', assign: 'Asignar responsable', 'nav-info': 'Exportación NAV pendiente',
}[modal.value ?? 'nav-info']))
const needsNote = computed(() => modal.value && ['ph-approve', 'ph-changes', 'ph-edit', 'pbc-apt', 'pbc-issue', 'pbc-no', 'prior', 'doc-reject', 'it-report', 'it-resolve', 'call'].includes(modal.value))
const needsReference = computed(() => modal.value && ['nav', 'criteria', 'present', 'invoice'].includes(modal.value))
const needsDate = computed(() => modal.value === 'criteria' || modal.value === 'present')

function perform(action: WorkflowAction) {
  const result = act(item.value.id, action)
  feedback.value = result
  return result.ok
}
function open(mode: Modal, id = '') {
  modal.value = mode; note.value = ''; reference.value = ''; fee.value = item.value.fee; actionDate.value = today.value; docId.value = id; owner.value = item.value.owner
}
function submit() {
  let action: WorkflowAction
  switch (modal.value) {
    case 'ph-approve': action = { type: 'ph-review', approve: true, note: note.value }; break
    case 'ph-changes': action = { type: 'ph-review', approve: false, note: note.value }; break
    case 'ph-edit': action = { type: 'ph-edit', note: note.value, fee: fee.value }; break
    case 'pbc-apt': action = { type: 'pbc-decide', state: 'Apto', note: note.value }; break
    case 'pbc-issue': action = { type: 'pbc-decide', state: 'Incidencia', note: note.value }; break
    case 'pbc-no': action = { type: 'pbc-decide', state: 'No apto', note: note.value }; break
    case 'nav': action = { type: 'nav-register', reference: reference.value }; break
    case 'prior': action = { type: 'prior-confirm', note: note.value }; break
    case 'doc-reject': action = { type: 'review-document', id: docId.value, valid: false, note: note.value }; break
    case 'criteria': action = { type: 'criteria', reference: reference.value, date: actionDate.value }; break
    case 'present': action = { type: 'present', receipt: reference.value, date: actionDate.value }; break
    case 'invoice': action = { type: 'invoice', number: reference.value }; break
    case 'it-report': action = { type: 'it-report', note: note.value }; break
    case 'it-resolve': action = { type: 'it-resolve', note: note.value }; break
    case 'call': action = { type: 'contact-outcome', outcome: callOutcome.value, note: note.value }; break
    case 'assign': action = { type: 'assign', owner: owner.value }; break
    default: return
  }
  if (perform(action)) modal.value = null
}
function demoDocument() { perform({ type: 'add-document', kind: fileKind.value, name: `${fileKind.value.toLowerCase().replaceAll(' ', '-')}-demo.pdf`, size: 120000 }) }
function phDownload() { downloadDemo(`PH-${item.value.id}-v${item.value.ph.version}-DEMO.txt`, `DOCUMENTO FICTICIO · SIN VALIDEZ\nPropuesta ${item.value.id} v${item.value.ph.version}\nCliente: ${item.value.name}\nAlcance: ${item.value.campaign} 2025, ${item.value.rentaType}, presentación ${item.value.presenter}\nHonorarios ilustrativos: ${money(item.value.fee)}\nCláusula de autorización de ejemplo; solo es efectiva tras validación independiente.\nEstado: ${item.value.ph.state}\n${item.value.ph.note}`) }
function excelDownload() { downloadDemo(`Excel-720-${item.value.id}-v${item.value.extraction.version ?? 1}-DEMO.csv`, '\uFEFFDEMO;NO ES XLSX NI IMPORTABLE EN CRITERIA\nOrigen;Entidad;País;Tipo;Valor ficticio;Observación\n' + rows.value.map(row => [row.origin, row.entity, row.country, row.category, row.value, row.observation].map(value => `"${String(value ?? '').replaceAll('"', '""')}"`).join(';')).join('\n'), 'text/csv;charset=utf-8') }
function receiptDownload() { downloadDemo(`Justificante-${item.value.id}-DEMO.txt`, `JUSTIFICANTE FICTICIO · SIN VALIDEZ FISCAL\n${item.value.tax.receipt}\nFecha demo: ${item.value.tax.presentationDate ?? today.value}\nNinguna presentación real realizada.`) }
function invoiceDownload() { downloadDemo(`Factura-${item.value.id}-DEMO.txt`, `FACTURA FICTICIA · SIN VALIDEZ CONTABLE\n${item.value.invoice.number}\nImporte ilustrativo ${money(item.value.invoice.amount)}\nCobro no confirmado.`) }
</script>

<template>
  <section>
    <NuxtLink to="/expedientes" class="back-link"><i class="pi pi-arrow-left" />Todos los expedientes</NuxtLink>
    <div class="page-heading detail-heading"><div class="client-title"><span class="avatar large" :class="item.campaign === '720' ? 'lavender' : 'mint'">{{ initials(item.name) }}</span><div><p class="eyebrow">{{ item.id }} · EJERCICIO 2025</p><h1>{{ item.name }}</h1><p>{{ item.email }} · {{ item.segment }}</p></div></div><div class="heading-actions"><Tag :value="stage(item)" :severity="statusSeverity(item.tax.state)" /><NuxtLink :to="`/portal/${item.id}?token=demo-${item.id}`" class="primary-link"><i class="pi pi-external-link" />Previsualizar portal</NuxtLink></div></div>
    <div v-if="feedback" role="status" aria-live="polite" class="feedback"><Message :severity="feedback.ok ? 'success' : 'error'">{{ feedback.message }}</Message></div>
    <Message v-if="readonly" severity="info" class="feedback">Solo consulta. {{ item.tax.state === 'Cerrado' ? 'Expediente cerrado. No implica factura pagada.' : 'Cliente fuera de campaña; no habrá seguimientos.' }}</Message>
    <div class="case-summary"><div><small>CAMPAÑA</small><strong>{{ item.campaign === '720' ? 'Modelo 720' : 'Renta' }} · 2025</strong></div><div><small>RESPONSABLE</small><strong>{{ item.owner || 'Sin asignar' }}<Button icon="pi pi-pencil" text size="small" aria-label="Cambiar responsable" :disabled="readonly" @click="open('assign')" /></strong></div><div><small>HONORARIOS ILUSTRATIVOS</small><strong>{{ money(item.fee) }}</strong></div><div><small>SIGUIENTE PASO</small><strong>{{ nextTask(item, today) }}</strong></div></div>
    <div class="case-scenario"><i class="pi pi-flask" /><span>Escenario: {{ item.scenario }}</span><span>Rol actual: <strong>{{ role }}</strong></span></div>
    <div v-if="!item.opened" class="panel capture-panel"><h2>Captación · {{ item.contact }}</h2><p>Formulario del cliente disponible en el portal. Aceptar abre un único expediente y genera una PH sin enviarla.</p><div class="button-row"><Button label="Recordatorio (7 días)" icon="pi pi-envelope" :disabled="readonly" @click="perform({ type: 'remind' })" /><Button label="Crear tarea de llamada (+3 días)" severity="secondary" outlined :disabled="readonly" @click="perform({ type: 'call' })" /><Button label="Resultado de llamada" severity="secondary" outlined :disabled="readonly" @click="open('call')" /></div></div>
    <Tabs v-model:value="tab" class="case-tabs">
      <TabList><Tab value="ph">Propuesta y firma</Tab><Tab value="validation">Validaciones y alta</Tab><Tab value="docs">Documentación</Tab><Tab value="tax">{{ item.campaign === '720' ? 'Extracción y Criteria' : 'Borrador y presentación' }}</Tab><Tab value="close">Presentación y cierre</Tab><Tab value="history">Historial</Tab></TabList>
      <TabPanels>
        <TabPanel value="ph">
          <div class="detail-grid"><section class="panel"><div class="panel-heading"><div><h2>Propuesta de honorarios</h2><p>{{ item.ph.prior ? 'Antecedente importado, sin nueva PH' : `Versión ${item.ph.version} · Envío siempre manual` }}</p></div><Tag :value="item.ph.state" :severity="statusSeverity(item.ph.state)" /></div><div v-if="item.ph.prior"><Message severity="info">PH previa: no se generará otra propuesta ni firma. No se asumen aprobadas las validaciones históricas.</Message><p>{{ item.ph.note }}</p></div><template v-else><div class="document-preview"><span class="preview-icon"><i class="pi pi-file" /></span><div><strong>PH · {{ item.campaign }} 2025</strong><small>{{ item.rentaType }} · Presentación {{ item.presenter }} · {{ money(item.fee) }}</small></div><Button icon="pi pi-download" text aria-label="Descargar PH ficticia TXT" @click="phDownload" /></div><dl class="metadata"><div><dt>Aprobación socio</dt><dd>{{ item.ph.approvedVersion ? `v${item.ph.approvedVersion}` : 'Pendiente' }}</dd></div><div><dt>Firma cliente</dt><dd>{{ item.ph.signedVersion ? `v${item.ph.signedVersion} (ficticia)` : 'Pendiente' }}</dd></div><div><dt>Autorización</dt><dd>Cláusula de ejemplo; validación independiente</dd></div></dl><p v-if="item.ph.note" class="inline-note">{{ item.ph.note }}</p><div class="button-row"><Button v-if="['Borrador', 'Cambios solicitados'].includes(item.ph.state)" label="Solicitar revisión socio" :disabled="readonly" @click="perform({ type: 'ph-submit' })" /><template v-if="item.ph.state === 'En revisión'"><Button label="Aprobar PH" :disabled="readonly" @click="open('ph-approve')" /><Button label="Solicitar cambios" severity="secondary" outlined :disabled="readonly" @click="open('ph-changes')" /></template><Button v-if="item.ph.state === 'Aprobada'" label="Enviar PH manualmente" icon="pi pi-send" :disabled="readonly" @click="perform({ type: 'ph-send' })" /><Button v-if="!['Firmada', 'No necesaria'].includes(item.ph.state)" label="Editar propuesta" severity="secondary" outlined :disabled="readonly" @click="open('ph-edit')" /><Button v-if="item.ph.state === 'Enviada'" label="Llamada por firma (3 días)" severity="secondary" outlined :disabled="readonly" @click="perform({ type: 'ph-call' })" /></div></template></section><aside class="panel guidance"><i class="pi pi-compass" /><h3>Revisión, envío y firma.<br>Tres pasos distintos.</h3><p>Socio revisa la versión vigente. Profesional envía manualmente. Cliente responde desde su portal.</p><p>Rechazo de la PH permite renegociar; retirada definitiva detiene la campaña.</p><Button label="Registrar resultado de llamada" text :disabled="readonly" @click="open('call')" /></aside></div>
        </TabPanel>
        <TabPanel value="validation">
          <div class="detail-grid"><section class="panel"><div class="panel-heading"><div><h2>Identidad y representación</h2><p>Recepción de archivos no equivale a validación</p></div></div><div class="validation-row"><div><strong>DNI vigente · ambas caras</strong><small>{{ item.identity.dni ? 'Revisión favorable registrada' : 'Pte. DNI / revisión' }}</small></div><Tag :value="item.identity.dni ? 'Válido' : 'Pendiente'" :severity="item.identity.dni ? 'success' : 'warn'" /></div><div class="form-row"><label for="dni-until">Caducidad del DNI<InputText id="dni-until" v-model="dniUntil" type="date" /></label><Button :label="item.identity.dni ? 'Marcar pendiente' : 'Validar DNI'" severity="secondary" outlined :disabled="readonly" @click="perform({ type: 'identity', field: 'dni', value: !item.identity.dni, validUntil: dniUntil })" /><Button label="Solicitar DNI" text :disabled="readonly || item.identity.dni" @click="perform({ type: 'request-identity' })" /></div><div v-for="field in (['certificate', 'authorization'] as const)" :key="field" class="validation-row"><div><strong>{{ field === 'certificate' ? 'Certificado digital' : 'Autorización de presentación' }}</strong><small>{{ item.presenter === 'Cliente' && item.campaign === 'Renta' ? 'No aplica a presentación por cliente' : 'Requerido para presentación por RCD, no para revisar documentos' }}</small></div><Button :label="item.identity[field] ? 'Disponible' : 'Registrar disponible'" :severity="item.identity[field] ? 'success' : 'secondary'" outlined :disabled="readonly || (item.presenter === 'Cliente' && item.campaign === 'Renta')" @click="perform({ type: 'identity', field, value: !item.identity[field] })" /></div><template v-if="item.ph.prior"><Message severity="warn">Antecedentes importados. Confirmarlos manualmente no genera alta nueva.</Message><Button :label="item.ph.priorConfirmed ? 'Antecedentes confirmados' : 'Confirmar antecedentes históricos'" :disabled="readonly || item.ph.priorConfirmed" @click="open('prior')" /></template></section><section class="panel"><div class="panel-heading"><div><h2>PBC y alta NAV</h2><p>Control humano · Integraciones no conectadas</p></div><Tag :value="item.pbc" :severity="statusSeverity(item.pbc)" /></div><p v-if="item.pbcNote" class="inline-note">{{ item.pbcNote }}</p><div class="button-row"><Button label="Iniciar filtros PBC simulados" severity="secondary" outlined :disabled="readonly || item.ph.prior" @click="perform({ type: 'pbc-start' })" /><Button label="Continuar tras revisión" :disabled="readonly || item.ph.prior" @click="open('pbc-apt')" /><Button label="Incidencia" severity="warn" outlined :disabled="readonly || item.ph.prior" @click="open('pbc-issue')" /><Button label="No apto" severity="danger" text :disabled="readonly || item.ph.prior" @click="open('pbc-no')" /></div><div class="section-separator" /><div class="validation-row"><div><strong>NAV · {{ item.nav || (item.ph.prior ? 'Antecedente histórico, sin nueva alta' : 'Alta pendiente') }}</strong><small>Confirmación manual por equipo Altas; aviso local al paralegal</small></div></div><div class="button-row"><Button label="Registrar alta NAV" :disabled="readonly || !!item.nav || item.ph.prior" @click="open('nav')" /><Button label="Ver exportación pendiente" severity="secondary" text @click="open('nav-info')" /></div></section></div>
        </TabPanel>
        <TabPanel value="docs">
          <section class="panel"><div class="panel-heading"><div><h2>Documentación del cliente</h2><p>Requisitos ilustrativos: {{ requiredKinds(item).join(' · ') }}</p></div><Tag :value="item.docsComplete ? 'Completa' : item.delivered ? 'Enviado para revisión' : 'Pendiente de entrega'" :severity="item.docsComplete ? 'success' : 'warn'" /></div><div class="button-row"><Button label="Enviar acceso documental" icon="pi pi-link" :disabled="readonly || item.portalSent" @click="perform({ type: 'portal-send' })" /><Select v-model="fileKind" :options="documentKinds" aria-label="Tipo de documento de muestra" /><Button label="Añadir muestra ficticia" icon="pi pi-plus" severity="secondary" outlined :disabled="readonly" @click="demoDocument" /></div><Message v-if="missingKinds(item).length" severity="warn" class="feedback">Pendientes de validar: {{ missingKinds(item).join(', ') }}.</Message><p class="footnote">Añadir una muestra no la entrega ni la valida. Cliente debe entregar tanda desde portal. Sustituir invalida preparación vigente sin borrar presentaciones ya registradas.</p><DataTable :value="currentDocuments(item)" data-key="id"><template #empty><div class="empty-note">No hay documentos. Incorpora una muestra o abre el portal.</div></template><Column header="DOCUMENTO"><template #body="{ data }"><strong>{{ data.kind }}</strong><small class="table-small">{{ data.name }}</small></template></Column><Column header="VERSIÓN"><template #body="{ data }">v{{ data.version }}</template></Column><Column header="ESTADO"><template #body="{ data }"><Tag :value="data.state" :severity="statusSeverity(data.state)" /></template></Column><Column field="note" header="OBSERVACIONES" /><Column header="REVISIÓN"><template #body="{ data }"><div class="button-row"><Button label="Validar" size="small" text :disabled="readonly || !item.delivered || data.state === 'Válido'" @click="perform({ type: 'review-document', id: data.id, valid: true, note: '' })" /><Button label="Sustituir" size="small" text severity="danger" :disabled="readonly || !item.delivered" @click="open('doc-reject', data.id)" /></div></template></Column></DataTable><div class="panel-actions"><Button label="Confirmar documentación completa" icon="pi pi-check-circle" :disabled="readonly || item.docsComplete" @click="perform({ type: 'complete-documents' })" /></div></section>
        </TabPanel>
        <TabPanel value="tax">
          <template v-if="item.campaign === 'Renta'"><div class="detail-grid"><section class="panel"><div class="panel-heading"><div><h2>Borrador de Renta</h2><p>Versión {{ item.tax.version || 'sin preparar' }} · Presenta {{ item.presenter }}</p></div><Tag :value="item.tax.state" :severity="statusSeverity(item.tax.state)" /></div><p v-if="item.tax.note" class="inline-note">{{ item.tax.note }}</p><div class="document-preview"><i class="pi pi-file-edit preview-icon" /><div><strong>Declaración ficticia · {{ item.rentaType }}</strong><small>Base y resultado ilustrativos; sin cálculo fiscal real</small></div></div><div class="button-row"><Button label="Preparar nueva versión" :disabled="readonly" @click="perform({ type: 'tax-draft' })" /><Button label="Enviar borrador al cliente" icon="pi pi-send" severity="secondary" outlined :disabled="readonly || item.tax.state !== 'Borrador'" @click="perform({ type: 'tax-send' })" /></div><p class="footnote">Cambiar la versión invalida la aceptación anterior. Revisa el borrador desde el portal.</p><div v-for="draft in item.tax.drafts" :key="draft.version" class="draft-version"><strong>v{{ draft.version }}</strong><span>{{ dateLabel(draft.date) }} · {{ draft.note || 'Borrador ficticio' }}</span></div></section><aside class="panel guidance"><i class="pi pi-calendar" /><h3>{{ item.presenter === 'Cliente' ? 'Presenta el cliente' : 'Presenta RCD' }}</h3><p v-if="item.presenter === 'Cliente'">Aviso ilustrativo: plazo ficticio 30/06/2026. Esta advertencia no confirma presentación. Cliente registra fecha y referencia desde portal.</p><p v-else>Presentación requiere acuerdo sobre versión vigente, certificado y autorización. Confirma fecha y justificante ficticio en «Presentación y cierre».</p><p>Importes y plazos de demostración, no asesoramiento fiscal.</p></aside></div></template>
          <template v-else><section class="panel"><div class="panel-heading"><div><h2>Extractor 720 · Excel ficticio</h2><p>Activación manual · Versión {{ item.extraction.version ?? (item.extraction.rows.length ? 1 : 0) }}</p></div><Tag :value="item.extraction.state" :severity="statusSeverity(item.extraction.state)" /></div><Message v-if="item.extraction.state === 'Incidencia IT'" severity="error">{{ item.extraction.note }} Sin resultado válido; Criteria bloqueado. Incidencia separada de PBC.</Message><div class="button-row"><Button label="Activar extractor simulado" icon="pi pi-sparkles" :disabled="readonly" @click="perform({ type: 'extract', fail: false })" /><Button label="Simular fallo técnico" severity="secondary" outlined :disabled="readonly" @click="perform({ type: 'extract', fail: true })" /><Button label="Desviación a IT" severity="warn" outlined :disabled="readonly" @click="open('it-report')" /><Button v-if="item.extraction.state === 'Incidencia IT'" label="Registrar ajuste IT" severity="secondary" outlined :disabled="readonly" @click="open('it-resolve')" /></div><DataTable v-if="rows.length && item.extraction.state !== 'Incidencia IT'" :value="rows" class="excel-table"><Column field="origin" header="ORIGEN" /><Column header="ENTIDAD"><template #body="{ data }"><InputText v-model="data.entity" aria-label="Entidad" :disabled="item.extraction.state !== 'Extraído'" /></template></Column><Column header="PAÍS"><template #body="{ data }"><InputText v-model="data.country" aria-label="País" :disabled="item.extraction.state !== 'Extraído'" /></template></Column><Column field="category" header="TIPO DE BIEN" /><Column header="VALOR FICTICIO"><template #body="{ data }"><InputNumber v-model="data.value" :min="0" :use-grouping="false" aria-label="Valor ficticio" :disabled="item.extraction.state !== 'Extraído'" /></template></Column><Column header="OBSERVACIÓN"><template #body="{ data }"><InputText v-model="data.observation" aria-label="Observación" :disabled="item.extraction.state !== 'Extraído'" /></template></Column></DataTable><div class="button-row"><Button label="Validar Excel vigente" icon="pi pi-check" :disabled="readonly || item.extraction.state !== 'Extraído'" @click="perform({ type: 'extraction-review', rows })" /><Button label="Descargar representación CSV" icon="pi pi-download" severity="secondary" text :disabled="!rows.length || item.extraction.state === 'Incidencia IT'" @click="excelDownload" /><Button label="Registrar carga manual Criteria" :disabled="readonly || item.extraction.state !== 'Revisado'" @click="open('criteria')" /></div><p class="footnote">Representación ilustrativa, no XLSX ni formato importable. Criteria se carga fuera de esta app y se registra manualmente con versión, fecha y referencia.</p><div v-for="run in item.extraction.runs" :key="run.version" class="draft-version"><strong>v{{ run.version }}</strong><span>{{ dateLabel(run.date) }} · {{ run.failed ? 'Fallo técnico' : 'Resultado simulado' }} · {{ run.inputs.join(', ') }}</span></div><p v-if="item.extraction.criteriaVersion" class="inline-note">Carga Criteria v{{ item.extraction.criteriaVersion }} · {{ item.extraction.criteriaDate }} · {{ item.extraction.note }}</p></section></template>
        </TabPanel>
        <TabPanel value="close">
          <div class="detail-grid"><section class="panel"><div class="panel-heading"><div><h2>Presentación y justificante</h2><p>Presentador: {{ item.campaign === '720' ? 'RCD' : item.presenter }} · Ninguna conexión con AEAT</p></div><Tag :value="item.tax.state" :severity="statusSeverity(item.tax.state)" /></div><p v-if="item.tax.receipt" class="inline-note">{{ item.tax.receipt }} · {{ item.tax.presentationDate }}</p><div class="button-row"><Button label="Registrar presentación ficticia" :disabled="readonly || item.tax.state === 'Presentado' || (item.campaign === 'Renta' && item.presenter === 'Cliente')" @click="open('present')" /><Button label="Descargar justificante TXT" icon="pi pi-download" text :disabled="!item.tax.receipt" @click="receiptDownload" /><Button label="Enviar justificante (simulado)" severity="secondary" outlined :disabled="readonly || item.tax.receiptSent || (item.presenter === 'Cliente' && item.campaign === 'Renta')" @click="perform({ type: 'receipt-send' })" /></div><p class="footnote">{{ item.presenter === 'Cliente' && item.campaign === 'Renta' ? 'No aplica envío de justificante por RCD ni certificado de RCD. Cliente confirma presentación desde portal.' : item.tax.receiptSent ? 'Justificante enviado (simulación).' : 'Justificante pendiente de envío por RCD.' }}</p></section><section class="panel"><div class="panel-heading"><div><h2>Factura / minuta</h2><p>Importe ilustrativo · Cobro no confirmado</p></div><Tag :value="item.invoice.sent ? 'Enviado' : item.invoice.number ? 'Emitida' : 'Pendiente'" :severity="item.invoice.sent ? 'success' : 'secondary'" /></div><h3>{{ item.invoice.number || 'Sin factura' }}<span v-if="item.invoice.number"> · {{ money(item.invoice.amount) }}</span></h3><div class="button-row"><Button label="Emitir factura ficticia" :disabled="readonly || !!item.invoice.number" @click="open('invoice')" /><Button label="Descargar factura TXT" text :disabled="!item.invoice.number" @click="invoiceDownload" /><Button label="Enviar factura (simulado)" severity="secondary" outlined :disabled="readonly || !item.invoice.number || item.invoice.sent" @click="perform({ type: 'invoice-send' })" /></div><div class="section-separator" /><Button label="Cerrar expediente" icon="pi pi-check-circle" :disabled="readonly" @click="perform({ type: 'close' })" /><p class="footnote">Cierre requiere presentación, justificante según rama y factura enviada. Nunca implica cobro.</p></section></div>
        </TabPanel>
        <TabPanel value="history"><section class="panel"><div class="panel-heading"><div><h2>Historial del expediente</h2><p>Eventos de este caso, sin efectos externos</p></div><span class="soft-label">{{ item.history.length }} eventos</span></div><ol class="timeline"><li v-for="(event, index) in item.history" :key="index"><span class="timeline-dot" /><div><strong>{{ event.text }}</strong><small>{{ dateLabel(event.date) }} · {{ event.role }}</small></div></li></ol><h3>Versiones documentales conservadas</h3><div v-for="doc in item.documents" :key="doc.id" class="draft-version"><strong>{{ doc.kind }} v{{ doc.version }}</strong><span>{{ doc.name }} · {{ doc.state }} · {{ doc.note }}</span></div></section></TabPanel>
      </TabPanels>
    </Tabs>
    <Dialog :visible="modal !== null" modal :header="title" :style="{ width: '520px', maxWidth: '95vw' }" @update:visible="value => { if (!value) modal = null }">
      <Message v-if="modal === 'nav-info'" severity="info">Los campos y formato de exportación NAV están pendientes de definición. No hay fichero importable ni conexión real. Referencia manual solo de demostración.</Message>
      <template v-else><p class="dialog-intro">{{ modal === 'prior' ? 'Confirma qué antecedentes previos has revisado. No se crean PH ni altas nuevas; confirmación humana explícita, no aprobación automática.' : 'Acción exclusivamente local y ficticia. Cancelar no modifica expediente.' }}</p><label v-if="needsNote" for="action-note" class="field">Motivo / observaciones<Textarea id="action-note" v-model="note" rows="3" /></label><label v-if="modal === 'ph-edit'" for="action-fee" class="field">Honorarios ilustrativos (EUR)<InputNumber v-model="fee" input-id="action-fee" :min="1" mode="currency" currency="EUR" locale="es-ES" /></label><label v-if="needsReference" for="action-reference" class="field">{{ modal === 'invoice' ? 'Número de factura ficticia' : modal === 'present' ? 'Referencia / muestra de justificante ficticio' : 'Referencia ficticia' }}<InputText id="action-reference" v-model="reference" /></label><label v-if="needsDate" for="action-date" class="field">Fecha (reloj demo)<InputText id="action-date" v-model="actionDate" type="date" :max="today" /></label><label v-if="modal === 'call'" for="call-outcome" class="field">Resultado<Select v-model="callOutcome" input-id="call-outcome" :options="['Sigue interesado', 'Sin contacto', 'No interesado']" /></label><label v-if="modal === 'assign'" for="owner-select" class="field">Responsable<Select v-model="owner" input-id="owner-select" :options="['Lucía Torres', 'Carlos Vidal', 'Marta Soler']" /></label><Message v-if="feedback && !feedback.ok" severity="error" role="alert">{{ feedback.message }}</Message></template>
      <template #footer><Button :label="modal === 'nav-info' ? 'Cerrar' : 'Cancelar'" severity="secondary" @click="modal = null" /><Button v-if="modal !== 'nav-info'" label="Confirmar simulación" @click="submit" /></template>
    </Dialog>
  </section>
</template>
